var guids = UnityEditor.AssetDatabase.FindAssets("t:Prefab", new[] { "Assets/Prefabs/Rooms" });
var report = new System.Text.StringBuilder();
foreach(var guid in guids) {
    var path = UnityEditor.AssetDatabase.GUIDToAssetPath(guid);
    var prefab = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>(path);
    if (prefab == null) continue;
    var room = prefab.GetComponent<Room>();
    if (room == null) continue;
    var inst = UnityEngine.Object.Instantiate(prefab);
    var instRoom = inst.GetComponent<Room>();
    var dirs = new System.Collections.Generic.List<string>();
    if(instRoom.Exits != null) foreach(var e in instRoom.Exits) dirs.Add(e.direction.ToString());
    report.AppendLine($"{prefab.name} | Exits: {string.Join(", ", dirs)}");
    UnityEngine.Object.DestroyImmediate(inst);
}
System.IO.File.WriteAllText("AllRoomsExits.txt", report.ToString());
